    for (let i = 0; i <= NS; i++) { us[i] = ua + ((ub - ua) * i) / NS; hs[i] = lam(us[i]); }
    let ib = 0;
    for (let i = 1; i <= NS; i++) if (hs[i] < hs[ib]) ib = i;
